// Junta o painel e a semana de auditoria num texto curto para o time.
const painel = $('Ler o painel').first().json;
const auditoria = $input.first().json;

const porStatus = painel.por_status || {};
const eventos = auditoria.eventos || [];
const seteDias = Date.now() - 7 * 24 * 3600 * 1000;
const daSemana = eventos.filter((e) => new Date(e.data_hora).getTime() >= seteDias);

const contar = (tipo) => daSemana.filter((e) => e.tipo === tipo).length;
const total = Object.values(porStatus).reduce((s, n) => s + n, 0);

const linhas = [
  `SGA-TI — resumo da semana (${new Date().toLocaleDateString('pt-BR')})`,
  '',
  `Parque: ${total} equipamento(s).`,
  ...Object.entries(porStatus).filter(([, n]) => n > 0).map(([s, n]) => `  • ${s}: ${n}`),
  '',
  `Movimento dos últimos 7 dias: ${daSemana.length} evento(s).`,
  `  • Recebimentos: ${contar('Recebimento')}`,
  `  • Movimentações: ${contar('Movimentacao')}`,
  `  • Manutenções: ${contar('Manutencao')}`,
  `  • Descartes: ${contar('Descarte')}`,
  `  • Retificações: ${contar('Retificacao')}`,
];

if (painel.aprovacoes_pendentes > 0) {
  linhas.push('', `⚠ ${painel.aprovacoes_pendentes} descarte(s) esperando aprovação.`);
}
// A auditoria devolve o total real, e não só o que coube na página: se houver
// mais eventos do que vieram, o resumo precisa dizer.
if (auditoria.total > eventos.length) {
  linhas.push('', `(a consulta trouxe ${eventos.length} de ${auditoria.total} eventos)`);
}

return [{ json: { resumo: linhas.join('\n') } }];

// LIGUE AQUI o seu canal (Slack, e-mail, Telegram…).
